style:
:root{--bg:#EEECE7;--paper:#FAF9F6;--ink:#22211F;--mid:#7D7A73;--line:#C9C5BC;--faint:#E4E1DA;--acc:#2D62D8;--bad:#C2372D;--serif:"Iowan Old Style","Charter","Palatino Linotype",Georgia,"Noto Serif",serif;--mono:"SF Mono","JetBrains Mono",ui-monospace,Menlo,Consolas,"DejaVu Sans Mono",monospace}
*{box-sizing:border-box}
body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--serif)}
main{display:grid;gap:40px;justify-content:center;padding:48px 0}
h1{margin:0;font:500 15px var(--mono);color:var(--mid);letter-spacing:.02em}
.f{position:relative;width:1200px;height:700px;background:var(--paper);border:1px solid var(--faint);border-radius:8px;overflow:hidden}
.f header{position:absolute;left:64px;top:52px;display:flex;gap:14px;align-items:baseline;font-family:var(--mono)}
.num{font-size:14px;color:var(--ink);border:1px solid var(--line);border-radius:99px;width:28px;height:28px;display:inline-grid;place-items:center}
.kick{font-size:13px;letter-spacing:.08em;text-transform:uppercase;color:var(--mid)}
.t{position:absolute;left:64px;top:96px;width:860px;margin:0;font-size:28px;line-height:1.38;text-wrap:pretty}
.note{position:absolute;left:64px;bottom:26px;margin:0;font:13px var(--mono);color:var(--mid)}
.stage{position:absolute;left:0;top:226px;width:1200px;height:440px;overflow:visible}
.n{fill:var(--paper);stroke:var(--line);stroke-width:1.25}.n.tr{stroke:var(--ink);stroke-width:2}
.nt{font:17px var(--mono);fill:var(--ink);text-anchor:middle}
.sub{font:12px var(--mono);fill:var(--mid);text-anchor:middle;letter-spacing:.06em}
.e{fill:none;stroke-width:2}.e.ink{stroke:var(--mid)}.e.acc{stroke:var(--acc);stroke-width:3}.e.bad{stroke:var(--bad);stroke-width:2.5}
.m-ink{fill:var(--mid)}.m-acc{fill:var(--acc)}.m-bad{fill:var(--bad)}
.el{font:15px var(--mono);fill:var(--mid);text-anchor:middle}.el.acc{fill:var(--acc)}.st{text-anchor:start}.el.bad{fill:var(--bad)}
.lab,.rl,.colh{font:13px var(--mono);fill:var(--mid);letter-spacing:.04em}.colh{text-transform:uppercase}
.rl{font-size:15px;fill:var(--ink)}
.tok{fill:var(--acc)}
.c rect{fill:var(--paper);stroke-width:1.5}.c text{font:15px var(--mono);text-anchor:middle}
.c.ink rect{stroke:var(--ink)}.c.ink text{fill:var(--ink)}
.c.bad rect{stroke:var(--bad);fill:#FBEFEC}.c.bad text{fill:var(--bad)}
.c.acc rect{stroke:var(--acc);stroke-width:2.5}.c.acc text{fill:var(--acc)}
.ghost{opacity:.22}
.empty{fill:none;stroke:var(--acc);stroke-width:2;stroke-dasharray:4 4}
.split{stroke:var(--acc);stroke-width:2}.sl{font:12px var(--mono);fill:var(--acc);text-anchor:middle;letter-spacing:.06em;text-transform:uppercase}
.stop{stroke:var(--acc);stroke-width:4;stroke-linecap:round}
.rule{stroke:var(--faint)}
.ask{display:flex;align-items:center;gap:14px;height:40px;padding:0 16px;border:1px solid var(--line);border-radius:99px;background:#fff;font-size:17px;width:max-content;max-width:760px}
.ask .k{font:12px var(--mono);color:var(--mid);letter-spacing:.06em;text-transform:uppercase}
.ask .q{color:var(--ink)}
.ask .b{font:13px var(--mono);color:var(--ink);border-bottom:1px solid var(--line);cursor:pointer}
.sq.bad{fill:#FBEFEC;stroke:var(--bad);stroke-width:1.5}.sq.ink{fill:var(--paper);stroke:var(--ink);stroke-width:1.5}
